function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 10) return 'grid needs 1 to 10 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 10) return 'Each row needs 1 to 10 columns.';
  for (const line of grid) {
    if (line.length !== n) return 'All rows must have the same length.';
    if (line.some(v => !Number.isInteger(v) || v < 0 || v > 10)) return 'Every cell holds a whole number from 0 to 10.';
  }
  return null;
}

