function findMaxFish(grid) {
  // Union-find over water cells, then the heaviest component wins.
  const m = grid.length, n = grid[0].length;
  const parent = Array.from({ length: m * n }, (_, i) => i);
  const find = (x) => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 0) continue;
      if (i + 1 < m && grid[i + 1][j] > 0) parent[find(i * n + j)] = find((i + 1) * n + j);
      if (j + 1 < n && grid[i][j + 1] > 0) parent[find(i * n + j)] = find(i * n + j + 1);
    }
  }
  const totals = new Map();
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 0) continue;
      const root = find(i * n + j);
      totals.set(root, (totals.get(root) || 0) + grid[i][j]);
    }
  }
  return totals.size === 0 ? 0 : Math.max(...totals.values());
}

