function generate(rand, size) {
  const m = size === 'large' ? 10 : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 10 : 1 + Math.floor(rand() * 5);
  const style = Math.floor(rand() * 5);
  const water = style === 0 ? 0 : style === 1 ? 1 : 0.3 + rand() * 0.5;
  const grid = [];
  for (let i = 0; i < m; i++) {
    const line = [];
    for (let j = 0; j < n; j++) line.push(rand() < water ? 1 + Math.floor(rand() * 10) : 0);
    grid.push(line);
  }
  return [grid];
}
